"""Promo codes: discount rules and the registry that tracks validity and usage.

A promo code gives a percentage or a fixed discount on the participating lines of an
order (see README). The registry checks that a code exists, is active and is not used up.
Order conditions (minimum amount, participating lines) are checked by the pricing module.
"""

from __future__ import annotations

import logging
from dataclasses import dataclass
from datetime import datetime
from decimal import Decimal
from enum import StrEnum

from .catalog import Category, Product, normalize_key
from .clock import Clock, _require_aware
from .errors import (
    PromoConditionsError,
    PromoExpiredError,
    UnknownPromoCodeError,
    ValidationError,
)
from .money import ZERO, to_money

logger = logging.getLogger(__name__)

MAX_PERCENT = Decimal("100")


class DiscountKind(StrEnum):
    PERCENT = "percent"
    FIXED = "fixed"


@dataclass(frozen=True)
class PromoCode:
    code: str
    kind: DiscountKind
    value: Decimal
    min_order_amount: Decimal = ZERO
    starts_at: datetime | None = None
    expires_at: datetime | None = None
    max_uses: int | None = None
    excluded_categories: frozenset[Category] = frozenset()

    def __post_init__(self) -> None:
        object.__setattr__(self, "code", normalize_key(self.code))
        if not self.code:
            raise ValidationError("promo code must not be empty")
        if not isinstance(self.kind, DiscountKind):
            raise ValidationError(f"discount kind of {self.code} must be a DiscountKind")
        _require_finite(f"value of {self.code}", self.value)
        if self.kind is DiscountKind.PERCENT:
            if not Decimal("0") < self.value <= MAX_PERCENT:
                raise ValidationError(f"percent of {self.code} must be in (0, 100]")
        else:
            if self.value <= 0:
                raise ValidationError(f"fixed discount of {self.code} must be positive")
            if to_money(self.value) != self.value:
                raise ValidationError(f"fixed discount of {self.code} has more than two digits")
        _require_finite(f"minimum order of {self.code}", self.min_order_amount)
        if self.min_order_amount < 0 or to_money(self.min_order_amount) != self.min_order_amount:
            raise ValidationError(f"minimum order of {self.code} must be a non-negative amount")
        for moment in (self.starts_at, self.expires_at):
            if moment is not None:
                _require_aware(moment)
        if (
            self.starts_at is not None
            and self.expires_at is not None
            and self.starts_at >= self.expires_at
        ):
            raise ValidationError(f"promo {self.code} starts after it expires")
        if self.max_uses is not None and (
            isinstance(self.max_uses, bool)
            or not isinstance(self.max_uses, int)
            or self.max_uses < 1
        ):
            raise ValidationError(f"max uses of {self.code} must be None or >= 1")
        object.__setattr__(self, "excluded_categories", frozenset(self.excluded_categories))
        for category in self.excluded_categories:
            if not isinstance(category, Category):
                raise ValidationError(f"excluded category of {self.code} must be a Category")

    def covers(self, product: Product) -> bool:
        """Whether the code discounts the product: gift cards never, excluded categories never."""
        return product.is_physical and product.category not in self.excluded_categories


def _require_finite(name: str, value: Decimal) -> None:
    if not isinstance(value, Decimal) or not value.is_finite():
        raise ValidationError(f"{name} must be a finite Decimal")


class PromoRegistry:
    """In-memory promo codes with their usage counters."""

    def __init__(self, clock: Clock) -> None:
        self._clock = clock
        self._promos: dict[str, PromoCode] = {}
        self._uses: dict[str, int] = {}

    def add(self, promo: PromoCode) -> None:
        if promo.code in self._promos:
            raise ValidationError(f"duplicate promo code: {promo.code}")
        self._promos[promo.code] = promo
        self._uses[promo.code] = 0
        logger.debug("promo: added %s", promo.code)

    def resolve(self, code: str) -> PromoCode:
        """Return the promo code if it exists, is active now and is not used up."""
        promo = self._get(code)
        now = self._clock.now()
        if promo.starts_at is not None and now < promo.starts_at:
            raise PromoExpiredError(f"promo code {promo.code} has not started yet")
        if promo.expires_at is not None and now >= promo.expires_at:
            raise PromoExpiredError(f"promo code {promo.code} has expired")
        if promo.max_uses is not None and self._uses[promo.code] >= promo.max_uses:
            raise PromoConditionsError(f"promo code {promo.code} is used up")
        return promo

    def uses(self, code: str) -> int:
        return self._uses[self._get(code).code]

    def consume(self, code: str) -> None:
        """Count one successful use of the code. Call only for a placed order."""
        promo = self.resolve(code)
        self._uses[promo.code] += 1

    def release(self, code: str) -> None:
        """Give back one use, e.g. when the order that used the code is cancelled."""
        promo = self._get(code)
        self._uses[promo.code] -= 1

    def _get(self, code: str) -> PromoCode:
        key = normalize_key(code)
        try:
            return self._promos[key]
        except KeyError:
            raise UnknownPromoCodeError(f"unknown promo code: {code!r}") from None
"""Order total calculation: line amounts, tax and shipping.

Rules (see README):

* line amount = unit price x quantity;
* tax is charged on top of the price, per line, at the rate of the line's category,
  and rounded per line (ROUND_HALF_UP); the order tax is the sum of line taxes;
* shipping is a flat fee, free when the goods subtotal reaches the threshold;
  carts with gift cards only are not shipped at all;
* shipping is not taxed;
* a promo code discounts only the participating lines (see ``shop.promo``); the discount
  is split between them by largest remainder, in kopecks, so the lines add up exactly to
  the order discount; tax is charged on the line amount after its discount; the free
  shipping threshold is compared with the goods amount after the discount, but the
  discount does not change the shipping fee.
"""

from __future__ import annotations

import logging
from collections.abc import Mapping, Sequence
from dataclasses import dataclass, field
from decimal import Decimal
from types import MappingProxyType

from .catalog import Cart, CartLine, Category
from .errors import EmptyCartError, PromoConditionsError, ValidationError
from .money import ZERO, quantize_money, sum_money
from .promo import DiscountKind, PromoCode

logger = logging.getLogger(__name__)

DEFAULT_TAX_RATE = Decimal("0.20")
DEFAULT_TAX_RATES: Mapping[Category, Decimal] = MappingProxyType(
    {
        Category.BOOKS: Decimal("0.10"),
        Category.FOOD: Decimal("0.10"),
        Category.GIFT_CARD: Decimal("0"),
    }
)


@dataclass(frozen=True)
class TaxPolicy:
    rates: Mapping[Category, Decimal] = field(default_factory=lambda: DEFAULT_TAX_RATES)
    default_rate: Decimal = DEFAULT_TAX_RATE

    def __post_init__(self) -> None:
        for rate in (*self.rates.values(), self.default_rate):
            if not Decimal("0") <= rate < Decimal("1"):
                raise ValidationError(f"tax rate out of range: {rate}")

    def rate_for(self, category: Category) -> Decimal:
        return self.rates.get(category, self.default_rate)

    def tax_for(self, category: Category, taxable_amount: Decimal) -> Decimal:
        return quantize_money(taxable_amount * self.rate_for(category))


@dataclass(frozen=True)
class ShippingPolicy:
    fee: Decimal = Decimal("299.00")
    free_threshold: Decimal | None = Decimal("3000.00")

    def __post_init__(self) -> None:
        if self.fee < 0:
            raise ValidationError("shipping fee must not be negative")
        if self.free_threshold is not None and self.free_threshold < 0:
            raise ValidationError("free shipping threshold must not be negative")

    def cost_for(self, goods_amount: Decimal, *, needs_delivery: bool) -> Decimal:
        if not needs_delivery:
            return ZERO
        if self.free_threshold is not None and goods_amount >= self.free_threshold:
            return ZERO
        return quantize_money(self.fee)


@dataclass(frozen=True)
class LineTotal:
    sku: str
    category: Category
    quantity: int
    unit_price: Decimal
    amount: Decimal
    tax: Decimal
    discount: Decimal = ZERO


@dataclass(frozen=True)
class OrderTotal:
    lines: tuple[LineTotal, ...]
    subtotal: Decimal
    shipping: Decimal
    tax: Decimal
    total: Decimal
    discount: Decimal = ZERO

    @property
    def items_count(self) -> int:
        return sum(line.quantity for line in self.lines)


DEFAULT_SHIPPING = ShippingPolicy()
DEFAULT_TAX = TaxPolicy()


def calculate_total(
    cart: Cart,
    shipping: ShippingPolicy | None = None,
    tax: TaxPolicy | None = None,
    *,
    promo: PromoCode | None = None,
) -> OrderTotal:
    """Calculate the totals of ``cart``. Pure function: does not modify the cart.

    ``promo`` must already be resolved by the registry (exists, active, not used up);
    this function checks only the order conditions of the code.
    """
    if cart.is_empty:
        raise EmptyCartError("cannot calculate total of an empty cart")
    shipping = shipping or DEFAULT_SHIPPING
    tax = tax or DEFAULT_TAX

    discounts = _line_discounts(cart.lines, promo)
    lines: list[LineTotal] = []
    for cart_line, discount in zip(cart.lines, discounts):
        product = cart_line.product
        amount = cart_line.amount
        lines.append(
            LineTotal(
                sku=product.sku,
                category=product.category,
                quantity=cart_line.quantity,
                unit_price=product.price,
                amount=amount,
                tax=tax.tax_for(product.category, amount - discount),
                discount=discount,
            )
        )

    subtotal = sum_money(line.amount for line in lines)
    discount_total = sum_money(line.discount for line in lines)
    needs_delivery = any(line.product.is_physical for line in cart.lines)
    shipping_cost = shipping.cost_for(subtotal - discount_total, needs_delivery=needs_delivery)
    tax_total = sum_money(line.tax for line in lines)
    total = subtotal - discount_total + shipping_cost + tax_total

    logger.debug(
        "total: subtotal=%s discount=%s shipping=%s tax=%s total=%s",
        subtotal,
        discount_total,
        shipping_cost,
        tax_total,
        total,
    )
    return OrderTotal(
        lines=tuple(lines),
        subtotal=subtotal,
        shipping=shipping_cost,
        tax=tax_total,
        total=total,
        discount=discount_total,
    )


def _line_discounts(lines: Sequence[CartLine], promo: PromoCode | None) -> list[Decimal]:
    """Discount of every line, aligned with ``lines``; zero for non-participating lines."""
    if promo is None:
        return [ZERO for _ in lines]

    participating = [promo.covers(line.product) for line in lines]
    if not any(participating):
        raise PromoConditionsError(f"promo code {promo.code} does not apply to the cart items")
    base = sum_money(line.amount for line, ok in zip(lines, participating) if ok)
    if base < promo.min_order_amount:
        raise PromoConditionsError(
            f"promo code {promo.code} requires goods of at least {promo.min_order_amount}"
        )

    if promo.kind is DiscountKind.PERCENT:
        discount = quantize_money(base * promo.value / 100)
    else:
        discount = min(promo.value, base)
    return _split_discount(lines, participating, discount)


def _split_discount(
    lines: Sequence[CartLine], participating: Sequence[bool], discount: Decimal
) -> list[Decimal]:
    """Share ``discount`` between participating lines in proportion to their amounts.

    Each share is rounded down to a kopeck; the leftover kopecks go one by one to the
    lines with the largest rounding remainder. A tie goes to the line earlier in the cart.
    Works in whole kopecks, so the result is exact.
    """
    base = sum(int(line.amount * 100) for line, ok in zip(lines, participating) if ok)
    discount_kopecks = int(discount * 100)

    shares: dict[int, list[int]] = {}
    for index, (line, ok) in enumerate(zip(lines, participating)):
        if ok:
            floor, remainder = divmod(discount_kopecks * int(line.amount * 100), base)
            shares[index] = [floor, remainder]
    leftover = discount_kopecks - sum(floor for floor, _ in shares.values())
    by_remainder = sorted(shares, key=lambda index: (-shares[index][1], index))
    for index in by_remainder[:leftover]:
        shares[index][0] += 1

    result = [ZERO for _ in lines]
    for index, (kopecks, _) in shares.items():
        result[index] = quantize_money(Decimal(kopecks) / 100)
    return result

