        cap = quantize_money(base * FIXED_DISCOUNT_MAX_SHARE)
        discount = min(promo.value, cap)
    return _split_discount(lines, participating, discount)


def _split_discount(
    lines: Sequence[CartLine], participating: Sequence[bool], discount: Decimal
) -> list[Decimal]:
    """Share ``discount`` between participating lines in proportion to their amounts.

    Each share is rounded down to a kopeck; the leftover kopecks go one by one to the
    lines with the largest rounding remainder. A tie goes to the line with the larger
    amount, and if the amounts are equal too, to the line earlier in the cart.
    Works in whole kopecks, so the result is exact.
    """
    base = sum(int(line.amount * 100) for line, ok in zip(lines, participating) if ok)
    discount_kopecks = int(discount * 100)

    shares: dict[int, list[int]] = {}
    for index, (line, ok) in enumerate(zip(lines, participating)):
        if ok:
            amount_kopecks = int(line.amount * 100)
            floor, remainder = divmod(discount_kopecks * amount_kopecks, base)
            shares[index] = [floor, remainder, amount_kopecks]
    leftover = discount_kopecks - sum(floor for floor, _, _ in shares.values())
    by_remainder = sorted(shares, key=lambda index: (-shares[index][1], -shares[index][2], index))
    for index in by_remainder[:leftover]:
        shares[index][0] += 1

    result = [ZERO for _ in lines]
    for index, (kopecks, _) in shares.items():
        result[index] = quantize_money(Decimal(kopecks) / 100)
    return result

"""Orders: placing, storing and cancelling."""

from __future__ import annotations

import logging
from collections.abc import Iterator
from dataclasses import dataclass, replace
from datetime import datetime
from enum import StrEnum

from .catalog import Cart, normalize_key
from .clock import Clock, SystemClock
from .errors import InvalidOrderStateError, OrderNotFoundError, UnknownPromoCodeError
from .pricing import OrderTotal, ShippingPolicy, TaxPolicy, calculate_total
from .promo import PromoCode, PromoRegistry

logger = logging.getLogger(__name__)


class OrderStatus(StrEnum):
    PLACED = "placed"
    CANCELLED = "cancelled"


@dataclass(frozen=True)
class Order:
    order_id: str
    created_at: datetime
    total: OrderTotal
    status: OrderStatus = OrderStatus.PLACED
    promo_code: str | None = None


class OrderStore:
    """In-memory order storage. Orders are kept in insertion order."""

    def __init__(self) -> None:
        self._orders: dict[str, Order] = {}
        self._sequence = 0

    def next_id(self) -> str:
        self._sequence += 1
        return f"ORD-{self._sequence:06d}"

    def add(self, order: Order) -> None:
        self._orders[order.order_id] = order

    def save(self, order: Order) -> None:
        if order.order_id not in self._orders:
            raise OrderNotFoundError(order.order_id)
        self._orders[order.order_id] = order

    def get(self, order_id: str) -> Order:
        try:
            return self._orders[order_id]
        except KeyError:
            raise OrderNotFoundError(order_id) from None

    def __iter__(self) -> Iterator[Order]:
        return iter(list(self._orders.values()))

    def __len__(self) -> int:
        return len(self._orders)


class OrderService:
    def __init__(
        self,
        store: OrderStore | None = None,
        *,
        clock: Clock | None = None,
        shipping: ShippingPolicy | None = None,
        tax: TaxPolicy | None = None,
        promos: PromoRegistry | None = None,
    ) -> None:
        self.store = store if store is not None else OrderStore()
        self._clock = clock or SystemClock()
        self._shipping = shipping
        self._tax = tax
        self._promos = promos

